     1→# ================================================================
     2→# FreeLang Bootstrap Lexer (Week 1, Phase B-4)
     3→# TypeScript lexer.ts → FreeLang lexer.fl 변환
     4→# 소스 코드 → 토큰 변환
     5→#
     6→# 설계 철학:
     7→# - 렉서 상태를 구조체로 명시적 관리 (함수형)
     8→# - 모든 함수는 상태와 소스를 입력받아 새로운 상태 반환
     9→# - 부작용 제거 → 테스트 용이
    10→# ================================================================
    11→
    12→# 렉서 상태 구조
    13→fn createLexerState(source: string): string {
    14→  return {
    15→    "source": source,
    16→    "position": 0,
    17→    "line": 1,
    18→    "column": 1,
    19→    "tokens": []
    20→  }
    21→}
    22→
    23→# Token 구조 정의
    24→fn createToken(tokenType: string, value: string, line: i32, column: i32): string {
    25→  return {
    26→    "type": tokenType,
    27→    "value": value,
    28→    "line": line,
    29→    "column": column
    30→  }
    31→}
    32→
    33→# 문자 분류 함수
    34→fn isDigit(c: string): bool {
    35→  return c >= "0" and c <= "9"
    36→}
    37→
    38→fn isAlpha(c: string): bool {
    39→  return (c >= "a" and c <= "z") or
    40→         (c >= "A" and c <= "Z") or
    41→         c == "_"
    42→}
    43→
    44→fn isAlphaNumeric(c: string): bool {
    45→  return isAlpha(c) or isDigit(c)
    46→}
    47→
    48→fn isOperator(c: string): bool {
    49→  return c == "+" or c == "-" or c == "*" or c == "/" or
    50→         c == "%" or c == "=" or c == "<" or c == ">" or
    51→         c == "!" or c == "&" or c == "|"
    52→}
    53→
    54→fn isWhitespace(c: string): bool {
    55→  return c == " " or c == "\t" or c == "\r"
    56→}
    57→
    58→# 렉서 메인 함수 (상태 기반)
    59→fn tokenize(source: string): string {
    60→  state = createLexerState(source)
    61→
    62→  # 메인 루프
    63→  while state["position"] < len(source) {
    64→    # 공백과 주석 건너뛰기
    65→    state = skipWhitespaceAndComments(state)
    66→
    67→    if state["position"] >= len(source) {
    68→      break
    69→    }
    70→
    71→    currentChar = state["source"][state["position"]]
    72→
    73→    # 숫자
    74→    if isDigit(currentChar) {
    75→      state = readNumber(state)
    76→    }
    77→    # 문자열
    78→    else if currentChar == "\"" or currentChar == "'" {
    79→      state = readString(state, currentChar)
    80→    }
    81→    # 식별자 또는 키워드
    82→    else if isAlpha(currentChar) {
    83→      state = readIdentifierOrKeyword(state)
    84→    }
    85→    # 연산자 및 기호
    86→    else if isOperator(currentChar) {
    87→      state = readOperator(state)
    88→    }
    89→    # 괄호
    90→    else if currentChar == "(" {
    91→      state = addTokenState(state, "lparen", "(")
    92→      state["position"] = state["position"] + 1
    93→      state["column"] = state["column"] + 1
    94→    }
    95→    else if currentChar == ")" {
    96→      state = addTokenState(state, "rparen", ")")
    97→      state["position"] = state["position"] + 1
    98→      state["column"] = state["column"] + 1
    99→    }
   100→    else if currentChar == "{" {
   101→      state = addTokenState(state, "lbrace", "{")
   102→      state["position"] = state["position"] + 1
   103→      state["column"] = state["column"] + 1
   104→    }
   105→    else if currentChar == "}" {
   106→      state = addTokenState(state, "rbrace", "}")
   107→      state["position"] = state["position"] + 1
   108→      state["column"] = state["column"] + 1
   109→    }
   110→    else if currentChar == "[" {
   111→      state = addTokenState(state, "lbracket", "[")
   112→      state["position"] = state["position"] + 1
   113→      state["column"] = state["column"] + 1
   114→    }
   115→    else if currentChar == "]" {
   116→      state = addTokenState(state, "rbracket", "]")
   117→      state["position"] = state["position"] + 1
   118→      state["column"] = state["column"] + 1
   119→    }
   120→    # 구분자
   121→    else if currentChar == "," {
   122→      state = addTokenState(state, "comma", ",")
   123→      state["position"] = state["position"] + 1
   124→      state["column"] = state["column"] + 1
   125→    }
   126→    else if currentChar == ";" {
   127→      state = addTokenState(state, "semicolon", ";")
   128→      state["position"] = state["position"] + 1
   129→      state["column"] = state["column"] + 1
   130→    }
   131→    else if currentChar == ":" {
   132→      state = addTokenState(state, "colon", ":")
   133→      state["position"] = state["position"] + 1
   134→      state["column"] = state["column"] + 1
   135→    }
   136→    else if currentChar == "." {
   137→      state = addTokenState(state, "dot", ".")
   138→      state["position"] = state["position"] + 1
   139→      state["column"] = state["column"] + 1
   140→    }
   141→    else if currentChar == "\n" {
   142→      state = addTokenState(state, "newline", "\n")
   143→      state["position"] = state["position"] + 1
   144→      state["line"] = state["line"] + 1
   145→      state["column"] = 1
   146→    }
   147→    else {
   148→      # 알 수 없는 문자
   149→      print("Unknown character: " + currentChar)
   150→      state["position"] = state["position"] + 1
   151→      state["column"] = state["column"] + 1
   152→    }
   153→  }
   154→
   155→  # EOF 토큰
   156→  state = addTokenState(state, "eof", "")
   157→
   158→  return state["tokens"]
   159→}
   160→
   161→# 공백과 주석 건너뛰기
   162→fn skipWhitespaceAndComments(state: string): string {
   163→  while state["position"] < len(state["source"]) {
   164→    c = state["source"][state["position"]]
   165→
   166→    # 공백 건너뛰기
   167→    if c == " " or c == "\t" or c == "\r" {
   168→      state["position"] = state["position"] + 1
   169→      state["column"] = state["column"] + 1
   170→    }
   171→    # 주석 건너뛰기 (#)
   172→    else if c == "#" {
   173→      while state["position"] < len(state["source"]) and state["source"][state["position"]] != "\n" {
   174→        state["position"] = state["position"] + 1
   175→      }
   176→    }
   177→    else {
   178→      break
   179→    }
   180→  }
   181→
   182→  return state
   183→}
   184→
   185→# 숫자 읽기
   186→fn readNumber(state: string): string {
   187→  startCol = state["column"]
   188→  value = ""
   189→
   190→  while state["position"] < len(state["source"]) {
   191→    c = state["source"][state["position"]]
   192→
   193→    if isDigit(c) or c == "." {
   194→      value = value + c
   195→      state["position"] = state["position"] + 1
   196→      state["column"] = state["column"] + 1
   197→    }
   198→    else {
   199→      break
   200→    }
   201→  }
   202→
   203→  state = addTokenState(state, "number", value)
   204→  return state
   205→}
   206→
   207→# 문자열 읽기
   208→fn readString(state: string, quote: string): string {
   209→  startCol = state["column"]
   210→  state["position"] = state["position"] + 1  # 시작 따옴표 건너뛰기
   211→  state["column"] = state["column"] + 1
   212→
   213→  value = ""
   214→
   215→  while state["position"] < len(state["source"]) and state["source"][state["position"]] != quote {
   216→    c = state["source"][state["position"]]
   217→
   218→    if c == "\\" {
   219→      state["position"] = state["position"] + 1
   220→      state["column"] = state["column"] + 1
   221→
   222→      if state["position"] < len(state["source"]) {
   223→        escaped = state["source"][state["position"]]
   224→
   225→        if escaped == "n" {
   226→          value = value + "\n"
   227→        }
   228→        else if escaped == "t" {
   229→          value = value + "\t"
   230→        }
   231→        else if escaped == "r" {
   232→          value = value + "\r"
   233→        }
   234→        else if escaped == "\\" {
   235→          value = value + "\\"
   236→        }
   237→        else if escaped == "\"" {
   238→          value = value + "\""
   239→        }
   240→        else if escaped == "'" {
   241→          value = value + "'"
   242→        }
   243→        else {
   244→          value = value + escaped
   245→        }
   246→
   247→        state["position"] = state["position"] + 1
   248→        state["column"] = state["column"] + 1
   249→      }
   250→    }
   251→    else {
   252→      value = value + c
   253→      state["position"] = state["position"] + 1
   254→      state["column"] = state["column"] + 1
   255→
   256→      if c == "\n" {
   257→        state["line"] = state["line"] + 1
   258→        state["column"] = 1
   259→      }
   260→    }
   261→  }
   262→
   263→  if state["position"] >= len(state["source"]) {
   264→    print("Unterminated string")
   265→    return state
   266→  }
   267→
   268→  state["position"] = state["position"] + 1  # 끝 따옴표 건너뛰기
   269→  state["column"] = state["column"] + 1
   270→
   271→  state = addTokenState(state, "string", value)
   272→  return state
   273→}
   274→
   275→# 식별자 또는 키워드 읽기
   276→fn readIdentifierOrKeyword(state: string): string {
   277→  startCol = state["column"]
   278→  value = ""
   279→
   280→  while state["position"] < len(state["source"]) and isAlphaNumeric(state["source"][state["position"]]) {
   281→    value = value + state["source"][state["position"]]
   282→    state["position"] = state["position"] + 1
   283→    state["column"] = state["column"] + 1
   284→  }
   285→
   286→  # 키워드 목록
   287→  keywords = ["fn", "if", "else", "while", "for", "return", "let", "mut",
   288→              "true", "false", "null"]
   289→
   290→  tokenType = "identifier"
   291→
   292→  # 키워드 확인
   293→  i = 0
   294→  while i < len(keywords) {
   295→    if keywords[i] == value {
   296→      tokenType = "keyword"
   297→      break
   298→    }
   299→    i = i + 1
   300→  }
   301→
   302→  state = addTokenState(state, tokenType, value)
   303→  return state
   304→}
   305→
   306→# 연산자 읽기
   307→fn readOperator(state: string): string {
   308→  startCol = state["column"]
   309→  value = state["source"][state["position"]]
   310→  state["position"] = state["position"] + 1
   311→  state["column"] = state["column"] + 1
   312→
   313→  # 2자 연산자 확인
   314→  if state["position"] < len(state["source"]) {
   315→    next = state["source"][state["position"]]
   316→
   317→    # 2자 연산자들
   318→    if (value == "=" and next == "=") or
   319→       (value == "!" and next == "=") or
   320→       (value == "<" and next == "=") or
   321→       (value == ">" and next == "=") or
   322→       (value == "&" and next == "&") or
   323→       (value == "|" and next == "|") or
   324→       (value == "-" and next == ">") {
   325→      value = value + next
   326→      state["position"] = state["position"] + 1
   327→      state["column"] = state["column"] + 1
   328→    }
   329→  }
   330→
   331→  # 특수 연산자 처리
   332→  if value == "=" {
   333→    state = addTokenState(state, "equals", value)
   334→  }
   335→  else if value == "->" {
   336→    state = addTokenState(state, "arrow", value)
   337→  }
   338→  else {
   339→    state = addTokenState(state, "operator", value)
   340→  }
   341→
   342→  return state
   343→}
   344→
   345→# 토큰 추가 헬퍼
   346→fn addTokenState(state: string, tokenType: string, value: string): string {
   347→  token = createToken(tokenType, value, state["line"], state["column"])
   348→  state["tokens"] = state["tokens"] + [token]
   349→  return state
   350→}
   351→
   352→# ================================================================
   353→# 테스트 및 검증
   354→# ================================================================
   355→
   356→# 간단한 렉서 테스트
   357→fn testLexer(): string {
   358→  # 테스트 코드
   359→  testCases = [
   360→    "x = 42",
   361→    "print(x)",
   362→    "fn add(a, b) { return a + b }",
   363→    "if true { x = 1 }",
   364→    "str = \"hello\""
   365→  ]
   366→
   367→  i = 0
   368→  while i < len(testCases) {
   369→    code = testCases[i]
   370→    print("=" * 50)
   371→    print("Input: " + code)
   372→    print("-" * 50)
   373→
   374→    result = tokenize(code)
   375→
   376→    j = 0
   377→    while j < len(result) {
   378→      token = result[j]
   379→      print("  " + token["type"] + ": " + token["value"])
   380→      j = j + 1
   381→    }
   382→
   383→    i = i + 1
   384→  }
   385→}
   386→
   387→# 간단한 테스트 실행 (주석 처리 가능)
   388→# testLexer()
