     1→# ================================================================
     2→# FreeLang Bootstrap Parser (Week 2, Phase B-4)
     3→# TypeScript parser.ts → FreeLang parser.fl 변환
     4→# 토큰 → AST (Abstract Syntax Tree) 변환
     5→#
     6→# 구조:
     7→# 1. AST 노드 생성 함수들
     8→# 2. Parser 상태 관리
     9→# 3. parse() - 진입점
    10→# 4. statement() - 문장 파싱
    11→# 5. expression() - 식 파싱 (우선순위)
    12→# ================================================================
    13→
    14→# ================================================================
    15→# AST 노드 생성 함수들 (12+ 타입)
    16→# ================================================================
    17→
    18→# Statement 노드들
    19→fn createAssignment(variable: string, value: {}) {
    20→  return { "type": "assignment", "variable": variable, "value": value }
    21→}
    22→
    23→fn createFunctionDefinition(name: string, params: [], body: []) {
    24→  return { "type": "functionDefinition", "name": name, "params": params, "body": body }
    25→}
    26→
    27→fn createIfStatement(condition: {}, thenBranch: [], elseBranch: []) {
    28→  return { "type": "ifStatement", "condition": condition, "then": thenBranch, "else": elseBranch }
    29→}
    30→
    31→fn createWhileStatement(condition: {}, body: []) {
    32→  return { "type": "whileStatement", "condition": condition, "body": body }
    33→}
    34→
    35→fn createReturnStatement(value: {}) {
    36→  return { "type": "returnStatement", "value": value }
    37→}
    38→
    39→fn createBlockStatement(statements: []) {
    40→  return { "type": "blockStatement", "statements": statements }
    41→}
    42→
    43→# Expression 노드들
    44→fn createBinaryOp(left: {}, operator: string, right: {}) {
    45→  return { "type": "binaryOp", "left": left, "operator": operator, "right": right }
    46→}
    47→
    48→fn createUnaryOp(operator: string, operand: {}) {
    49→  return { "type": "unaryOp", "operator": operator, "operand": operand }
    50→}
    51→
    52→fn createCallExpression(callee: {}, args: []) {
    53→  return { "type": "call", "callee": callee, "arguments": args }
    54→}
    55→
    56→fn createIdentifier(name: string) {
    57→  return { "type": "identifier", "name": name }
    58→}
    59→
    60→fn createLiteral(value: {}, literalType: string) {
    61→  return { "type": "literal", "value": value, "literalType": literalType }
    62→}
    63→
    64→fn createArrayLiteral(elements: []) {
    65→  return { "type": "arrayLiteral", "elements": elements }
    66→}
    67→
    68→fn createArrayAccess(array: {}, index: {}) {
    69→  return { "type": "arrayAccess", "array": array, "index": index }
    70→}
    71→
    72→fn createArrayAssignment(array: {}, index: {}, value: {}) {
    73→  return { "type": "arrayAssignment", "array": array, "index": index, "value": value }
    74→}
    75→
    76→# ================================================================
    77→# Parser 상태 관리
    78→# ================================================================
    79→
    80→fn createParserState(tokens: []) {
    81→  return {
    82→    "tokens": tokens,
    83→    "position": 0
    84→  }
    85→}
    86→
    87→# 현재 토큰 접근
    88→fn currentToken(state: {}) {
    89→  if state["position"] < len(state["tokens"]) {
    90→    return state["tokens"][state["position"]]
    91→  }
    92→  return { "type": "eof", "value": "" }
    93→}
    94→
    95→# 다음 토큰 미리보기
    96→fn peekToken(state: {}, offset: int) {
    97→  pos = state["position"] + offset
    98→  if pos < len(state["tokens"]) {
    99→    return state["tokens"][pos]
   100→  }
   101→  return { "type": "eof", "value": "" }
   102→}
   103→
   104→# 토큰 이동
   105→fn advance(state: {}) {
   106→  state["position"] = state["position"] + 1
   107→  return state
   108→}
   109→
   110→# 토큰 매칭
   111→fn match(state: {}, expectedType: string, expectedValue: string) {
   112→  token = currentToken(state)
   113→  if token["type"] == expectedType and (expectedValue == "" or token["value"] == expectedValue) {
   114→    state = advance(state)
   115→    return { "matched": true, "state": state, "token": token }
   116→  }
   117→  return { "matched": false, "state": state, "token": null }
   118→}
   119→
   120→# ================================================================
   121→# Parse 진입점 (메인 함수)
   122→# ================================================================
   123→
   124→fn parse(tokens: []) {
   125→  state = createParserState(tokens)
   126→  statements = []
   127→
   128→  # 메인 루프: EOF까지 문장 파싱
   129→  while currentToken(state)["type"] != "eof" {
   130→    # 빈 줄 건너뛰기
   131→    if currentToken(state)["type"] == "newline" {
   132→      state = advance(state)
   133→    }
   134→    else {
   135→      stmt = parseStatement(state)
   136→      if stmt != null {
   137→        statements = statements + [stmt]
   138→      }
   139→      state = stmt["_state"]
   140→    }
   141→  }
   142→
   143→  return statements
   144→}
   145→
   146→# ================================================================
   147→# Statement 파싱
   148→# ================================================================
   149→
   150→fn parseStatement(state: {}) {
   151→  token = currentToken(state)
   152→
   153→  # 함수 정의
   154→  if token["type"] == "keyword" and token["value"] == "fn" {
   155→    return parseFunctionDefinition(state)
   156→  }
   157→  # if 문
   158→  else if token["type"] == "keyword" and token["value"] == "if" {
   159→    return parseIfStatement(state)
   160→  }
   161→  # while 루프
   162→  else if token["type"] == "keyword" and token["value"] == "while" {
   163→    return parseWhileStatement(state)
   164→  }
   165→  # return 문
   166→  else if token["type"] == "keyword" and token["value"] == "return" {
   167→    return parseReturnStatement(state)
   168→  }
   169→  # 블록
   170→  else if token["type"] == "lbrace" {
   171→    return parseBlockStatement(state)
   172→  }
   173→  # 식 문장
   174→  else {
   175→    return parseExpressionStatement(state)
   176→  }
   177→}
   178→
   179→# 식 문장
   180→fn parseExpressionStatement(state: {}) {
   181→  expr = parseExpression(state)
   182→  state = expr["_state"]
   183→
   184→  # 세미콜론 또는 줄바꿈 선택적
   185→  if currentToken(state)["type"] == "semicolon" {
   186→    state = advance(state)
   187→  }
   188→  else if currentToken(state)["type"] == "newline" {
   189→    state = advance(state)
   190→  }
   191→
   192→  return { "_state": state, "result": expr }
   193→}
   194→
   195→# 함수 정의
   196→fn parseFunctionDefinition(state: {}) {
   197→  # fn 키워드 건너뛰기
   198→  state = advance(state)
   199→
   200→  # 함수 이름
   201→  nameToken = currentToken(state)
   202→  if nameToken["type"] != "identifier" {
   203→    print("Expected identifier after 'fn'")
   204→    return { "_state": state, "result": null }
   205→  }
   206→  funcName = nameToken["value"]
   207→  state = advance(state)
   208→
   209→  # 매개변수 목록
   210→  params = []
   211→  if currentToken(state)["type"] == "lparen" {
   212→    state = advance(state)
   213→
   214→    while currentToken(state)["type"] != "rparen" {
   215→      paramToken = currentToken(state)
   216→      if paramToken["type"] == "identifier" {
   217→        params = params + [paramToken["value"]]
   218→        state = advance(state)
   219→
   220→        # 타입 주석 건너뛰기 (optional)
   221→        if currentToken(state)["type"] == "colon" {
   222→          state = advance(state)
   223→          # 타입 정보 무시
   224→          state = advance(state)
   225→        }
   226→
   227→        # 쉼표
   228→        if currentToken(state)["type"] == "comma" {
   229→          state = advance(state)
   230→        }
   231→      }
   232→      else {
   233→        print("Expected parameter name")
   234→        state = advance(state)
   235→      }
   236→    }
   237→
   238→    state = advance(state)  # rparen
   239→  }
   240→
   241→  # 함수 본문
   242→  body = []
   243→  if currentToken(state)["type"] == "lbrace" {
   244→    blockStmt = parseBlockStatement(state)
   245→    state = blockStmt["_state"]
   246→    body = blockStmt["result"]["statements"]
   247→  }
   248→
   249→  funcDef = createFunctionDefinition(funcName, params, body)
   250→  return { "_state": state, "result": funcDef }
   251→}
   252→
   253→# if 문
   254→fn parseIfStatement(state: {}) {
   255→  # if 키워드 건너뛰기
   256→  state = advance(state)
   257→
   258→  # 조건
   259→  condition = parseExpression(state)
   260→  state = condition["_state"]
   261→
   262→  # then 블록
   263→  thenBlock = parseBlockStatement(state)
   264→  state = thenBlock["_state"]
   265→  thenBranch = thenBlock["result"]["statements"]
   266→
   267→  # else 블록 (optional)
   268→  elseBranch = []
   269→  if currentToken(state)["type"] == "keyword" and currentToken(state)["value"] == "else" {
   270→    state = advance(state)
   271→
   272→    elseBlock = parseBlockStatement(state)
   273→    state = elseBlock["_state"]
   274→    elseBranch = elseBlock["result"]["statements"]
   275→  }
   276→
   277→  ifStmt = createIfStatement(condition, thenBranch, elseBranch)
   278→  return { "_state": state, "result": ifStmt }
   279→}
   280→
   281→# while 루프
   282→fn parseWhileStatement(state: {}) {
   283→  # while 키워드 건너뛰기
   284→  state = advance(state)
   285→
   286→  # 조건
   287→  condition = parseExpression(state)
   288→  state = condition["_state"]
   289→
   290→  # 루프 본문
   291→  body = []
   292→  if currentToken(state)["type"] == "lbrace" {
   293→    blockStmt = parseBlockStatement(state)
   294→    state = blockStmt["_state"]
   295→    body = blockStmt["result"]["statements"]
   296→  }
   297→
   298→  whileStmt = createWhileStatement(condition, body)
   299→  return { "_state": state, "result": whileStmt }
   300→}
   301→
   302→# return 문
   303→fn parseReturnStatement(state: {}) {
   304→  # return 키워드 건너뛰기
   305→  state = advance(state)
   306→
   307→  # 반환값 (optional)
   308→  value = null
   309→  if currentToken(state)["type"] != "newline" and currentToken(state)["type"] != "eof" {
   310→    exprResult = parseExpression(state)
   311→    state = exprResult["_state"]
   312→    value = exprResult
   313→  }
   314→
   315→  retStmt = createReturnStatement(value)
   316→  return { "_state": state, "result": retStmt }
   317→}
   318→
   319→# 블록 문
   320→fn parseBlockStatement(state: {}) {
   321→  if currentToken(state)["type"] != "lbrace" {
   322→    print("Expected '{'")
   323→    return { "_state": state, "result": { "type": "blockStatement", "statements": [] } }
   324→  }
   325→
   326→  state = advance(state)  # lbrace
   327→  statements = []
   328→
   329→  while currentToken(state)["type"] != "rbrace" and currentToken(state)["type"] != "eof" {
   330→    if currentToken(state)["type"] == "newline" {
   331→      state = advance(state)
   332→    }
   333→    else {
   334→      stmt = parseStatement(state)
   335→      if stmt != null {
   336→        statements = statements + [stmt["result"]]
   337→      }
   338→      state = stmt["_state"]
   339→    }
   340→  }
   341→
   342→  if currentToken(state)["type"] == "rbrace" {
   343→    state = advance(state)
   344→  }
   345→
   346→  blockStmt = createBlockStatement(statements)
   347→  return { "_state": state, "result": blockStmt }
   348→}
