   350→# ================================================================
   351→# Expression 파싱 (우선순위 기반)
   352→# ================================================================
   353→
   354→# 최상위 (낮은 우선순위)
   355→fn parseExpression(state: {}) {
   356→  return parseAssignment(state)
   357→}
   358→
   359→# 할당 (= 연산자)
   360→fn parseAssignment(state: {}) {
   361→  expr = parseOr(state)
   362→  state = expr["_state"]
   363→
   364→  if currentToken(state)["type"] == "equals" {
   365→    state = advance(state)
   366→
   367→    # 좌변이 identifier 또는 arrayAccess
   368→    if expr["type"] == "identifier" {
   369→      value = parseAssignment(state)
   370→      state = value["_state"]
   371→
   372→      assignment = createAssignment(expr["name"], value)
   373→      return { "_state": state, "result": assignment }
   374→    }
   375→    else if expr["type"] == "arrayAccess" {
   376→      value = parseAssignment(state)
   377→      state = value["_state"]
   378→
   379→      assignment = createArrayAssignment(expr["array"], expr["index"], value)
   380→      return { "_state": state, "result": assignment }
   381→    }
   382→  }
   383→
   384→  return { "_state": state, "result": expr }
   385→}
   386→
   387→# OR 연산자 (||)
   388→fn parseOr(state: {}) {
   389→  left = parseAnd(state)
   390→  state = left["_state"]
   391→
   392→  while currentToken(state)["type"] == "operator" and currentToken(state)["value"] == "||" {
   393→    state = advance(state)
   394→    right = parseAnd(state)
   395→    state = right["_state"]
   396→
   397→    left = createBinaryOp(left, "||", right)
   398→  }
   399→
   400→  return { "_state": state, "result": left }
   401→}
   402→
   403→# AND 연산자 (&&)
   404→fn parseAnd(state: {}) {
   405→  left = parseEquality(state)
   406→  state = left["_state"]
   407→
   408→  while currentToken(state)["type"] == "operator" and currentToken(state)["value"] == "&&" {
   409→    state = advance(state)
   410→    right = parseEquality(state)
   411→    state = right["_state"]
   412→
   413→    left = createBinaryOp(left, "&&", right)
   414→  }
   415→
   416→  return { "_state": state, "result": left }
   417→}
   418→
   419→# 동등성 (==, !=)
   420→fn parseEquality(state: {}) {
   421→  left = parseComparison(state)
   422→  state = left["_state"]
   423→
   424→  while currentToken(state)["type"] == "operator" and
   425→        (currentToken(state)["value"] == "==" or currentToken(state)["value"] == "!=") {
   426→    op = currentToken(state)["value"]
   427→    state = advance(state)
   428→
   429→    right = parseComparison(state)
   430→    state = right["_state"]
   431→
   432→    left = createBinaryOp(left, op, right)
   433→  }
   434→
   435→  return { "_state": state, "result": left }
   436→}
   437→
   438→# 비교 (<, <=, >, >=)
   439→fn parseComparison(state: {}) {
   440→  left = parseAddition(state)
   441→  state = left["_state"]
   442→
   443→  while currentToken(state)["type"] == "operator" and
   444→        (currentToken(state)["value"] == "<" or
   445→         currentToken(state)["value"] == "<=" or
   446→         currentToken(state)["value"] == ">" or
   447→         currentToken(state)["value"] == ">=") {
   448→    op = currentToken(state)["value"]
   449→    state = advance(state)
   450→
   451→    right = parseAddition(state)
   452→    state = right["_state"]
   453→
   454→    left = createBinaryOp(left, op, right)
   455→  }
   456→
   457→  return { "_state": state, "result": left }
   458→}
   459→
   460→# 덧셈 (+, -)
   461→fn parseAddition(state: {}) {
   462→  left = parseMultiplication(state)
   463→  state = left["_state"]
   464→
   465→  while currentToken(state)["type"] == "operator" and
   466→        (currentToken(state)["value"] == "+" or currentToken(state)["value"] == "-") {
   467→    op = currentToken(state)["value"]
   468→    state = advance(state)
   469→
   470→    right = parseMultiplication(state)
   471→    state = right["_state"]
   472→
   473→    left = createBinaryOp(left, op, right)
   474→  }
   475→
   476→  return { "_state": state, "result": left }
   477→}
   478→
   479→# 곱셈 (*, /, %)
   480→fn parseMultiplication(state: {}) {
   481→  left = parseUnary(state)
   482→  state = left["_state"]
   483→
   484→  while currentToken(state)["type"] == "operator" and
   485→        (currentToken(state)["value"] == "*" or
   486→         currentToken(state)["value"] == "/" or
   487→         currentToken(state)["value"] == "%") {
   488→    op = currentToken(state)["value"]
   489→    state = advance(state)
   490→
   491→    right = parseUnary(state)
   492→    state = right["_state"]
   493→
   494→    left = createBinaryOp(left, op, right)
   495→  }
   496→
   497→  return { "_state": state, "result": left }
   498→}
   499→
   500→# 단항 연산 (-, !, &, &mut)
   501→fn parseUnary(state: {}) {
   502→  if currentToken(state)["type"] == "operator" and
   503→     (currentToken(state)["value"] == "-" or
   504→      currentToken(state)["value"] == "!" or
   505→      currentToken(state)["value"] == "&") {
   506→    op = currentToken(state)["value"]
   507→    state = advance(state)
   508→
   509→    # &mut 처리
   510→    if op == "&" and currentToken(state)["type"] == "keyword" and currentToken(state)["value"] == "mut" {
   511→      state = advance(state)
   512→      op = "&mut"
   513→    }
   514→
   515→    operand = parseUnary(state)
   516→    state = operand["_state"]
   517→
   518→    unary = createUnaryOp(op, operand)
   519→    return { "_state": state, "result": unary }
   520→  }
   521→
   522→  return parseCall(state)
   523→}
   524→
   525→# 함수 호출 (())
   526→fn parseCall(state: {}) {
   527→  expr = parsePrimary(state)
   528→  state = expr["_state"]
   529→
   530→  while true {
   531→    if currentToken(state)["type"] == "lparen" {
   532→      # 함수 호출
   533→      state = advance(state)
   534→      args = []
   535→
   536→      while currentToken(state)["type"] != "rparen" {
   537→        arg = parseExpression(state)
   538→        state = arg["_state"]
   539→        args = args + [arg]
   540→
   541→        if currentToken(state)["type"] == "comma" {
   542→          state = advance(state)
   543→        }
   544→      }
   545→
   546→      state = advance(state)  # rparen
   547→      expr = createCallExpression(expr, args)
   548→    }
   549→    else if currentToken(state)["type"] == "lbracket" {
   550→      # 배열 접근 ([])
   551→      state = advance(state)
   552→      index = parseExpression(state)
   553→      state = index["_state"]
   554→
   555→      if currentToken(state)["type"] == "rbracket" {
   556→        state = advance(state)
   557→      }
   558→
   559→      expr = createArrayAccess(expr, index)
   560→    }
   561→    else {
   562→      break
   563→    }
   564→  }
   565→
   566→  return { "_state": state, "result": expr }
   567→}
   568→
   569→# 기본 표현식
   570→fn parsePrimary(state: {}) {
   571→  token = currentToken(state)
   572→
   573→  # 숫자
   574→  if token["type"] == "number" {
   575→    state = advance(state)
   576→    return { "_state": state, "result": createLiteral(token["value"], "number") }
   577→  }
   578→  # 문자열
   579→  else if token["type"] == "string" {
   580→    state = advance(state)
   581→    return { "_state": state, "result": createLiteral(token["value"], "string") }
   582→  }
   583→  # true, false
   584→  else if token["type"] == "keyword" and (token["value"] == "true" or token["value"] == "false") {
   585→    state = advance(state)
   586→    return { "_state": state, "result": createLiteral(token["value"], "boolean") }
   587→  }
   588→  # null
   589→  else if token["type"] == "keyword" and token["value"] == "null" {
   590→    state = advance(state)
   591→    return { "_state": state, "result": createLiteral(null, "null") }
   592→  }
   593→  # 배열 리터럴 ([])
   594→  else if token["type"] == "lbracket" {
   595→    state = advance(state)
   596→    elements = []
   597→
   598→    while currentToken(state)["type"] != "rbracket" {
   599→      elem = parseExpression(state)
   600→      state = elem["_state"]
   601→      elements = elements + [elem]
   602→
   603→      if currentToken(state)["type"] == "comma" {
   604→        state = advance(state)
   605→      }
   606→    }
   607→
   608→    state = advance(state)  # rbracket
   609→    return { "_state": state, "result": createArrayLiteral(elements) }
   610→  }
   611→  # 괄호 표현식
   612→  else if token["type"] == "lparen" {
   613→    state = advance(state)
   614→    expr = parseExpression(state)
   615→    state = expr["_state"]
   616→
   617→    if currentToken(state)["type"] == "rparen" {
   618→      state = advance(state)
   619→    }
   620→
   621→    return { "_state": state, "result": expr }
   622→  }
   623→  # 식별자
   624→  else if token["type"] == "identifier" {
   625→    state = advance(state)
   626→    return { "_state": state, "result": createIdentifier(token["value"]) }
   627→  }
   628→  else {
   629→    print("Unexpected token: " + token["type"])
   630→    return { "_state": state, "result": null }
   631→  }
   632→}
