    61→
    62→# 이진 연산자
    63→fn evalBinaryOp(left: any, right: any, op: string): any {
    64→  if op == "+" {
    65→    # 문자열 또는 숫자 덧셈
    66→    if left is string or right is string {
    67→      return toString(left) + toString(right)
    68→    } else {
    69→      return left + right
    70→    }
    71→  } else if op == "-" {
    72→    return left - right
    73→  } else if op == "*" {
    74→    return left * right
    75→  } else if op == "/" {
    76→    return left / right
    77→  } else if op == "%" {
    78→    return left % right
    79→  } else if op == "==" {
    80→    return left == right
    81→  } else if op == "!=" {
    82→    return left != right
    83→  } else if op == "<" {
    84→    return left < right
    85→  } else if op == ">" {
    86→    return left > right
    87→  } else if op == "<=" {
    88→    return left <= right
    89→  } else if op == ">=" {
    90→    return left >= right
    91→  } else if op == "&&" or op == "and" {
    92→    return left and right
    93→  } else if op == "||" or op == "or" {
    94→    return left or right
    95→  } else {
    96→    return null
    97→  }
    98→}
