    10→
    11→pub enum FaultType {
    12→    LatencySpike(u64),           // milliseconds (5ms ~ 500ms)
    13→    MemoryLeak(u64),             // bytes (1MB ~ 100MB)
    14→    GCPause(u32),                // milliseconds (50ms ~ 200ms)
    15→    IOSaturation(u32),           // pending operations (10 ~ 100)
    16→    NetworkPartition,            // complete network disconnect
    17→    CPUThrottling(f64),          // percentage (50% ~ 100%)
    18→    ContextSwitchSpike(u32),     // multiplier from normal (2x ~ 5x)
    19→}
    20→
    21→impl FaultType {
    22→    pub fn name(&self) -> String {
    23→        match self {
    24→            FaultType::LatencySpike(ms) => format!("LatencySpike(+{}ms)", ms),
    25→            FaultType::MemoryLeak(bytes) => format!("MemoryLeak(+{}MB)", bytes / 1_000_000),
    26→            FaultType::GCPause(ms) => format!("GCPause({}ms)", ms),
    27→            FaultType::IOSaturation(count) => format!("IOSaturation({} ops)", count),
    28→            FaultType::NetworkPartition => "NetworkPartition".to_string(),
    29→            FaultType::CPUThrottling(pct) => format!("CPUThrottling({:.0}%)", pct),
    30→            FaultType::ContextSwitchSpike(mult) => format!("ContextSwitchSpike({}x)", mult),
    31→        }
    32→    }
    33→
    34→    pub fn severity(&self) -> u32 {
    35→        // 1-5 scale for impact assessment
    36→        match self {
    37→            FaultType::LatencySpike(ms) => {
    38→                if *ms > 300 { 5 } else if *ms > 200 { 4 } else { 3 }
    39→            },
    40→            FaultType::MemoryLeak(bytes) => {
    41→                let mb = *bytes / 1_000_000;
    42→                if mb > 50 { 5 } else if mb > 20 { 4 } else { 3 }
    43→            },
    44→            FaultType::GCPause(ms) => {
    45→                if *ms > 150 { 5 } else if *ms > 100 { 4 } else { 3 }
    46→            },
    47→            FaultType::IOSaturation(count) => {
    48→                if *count > 75 { 5 } else if *count > 50 { 4 } else { 3 }
    49→            },
    50→            FaultType::NetworkPartition => 5,
    51→            FaultType::CPUThrottling(pct) => {
    52→                if *pct < 30.0 { 5 } else if *pct < 50.0 { 4 } else { 3 }
    53→            },
    54→            FaultType::ContextSwitchSpike(mult) => {
    55→                if *mult > 4 { 5 } else if *mult > 3 { 4 } else { 3 }
    56→            },
    57→        }
    58→    }
    59→}
    60→
    61→// ============================================================================
    62→// Fault Instance & Timeline
    63→// ============================================================================
    64→
    65→pub struct FaultInstance {
    66→    fault_id: String,
    67→    fault_type: FaultType,
    68→    start_time_us: u64,
    69→    duration_ms: u32,
    70→    end_time_us: Option<u64>,
    71→    status: String, // "active", "completed", "failed"
    72→}
    73→
    74→impl FaultInstance {
    75→    pub fn is_active(&self, current_time_us: u64) -> bool {
    76→        if current_time_us < self.start_time_us {
    77→            return false;
    78→        }
    79→
    80→        let end_time = self.start_time_us + (self.duration_ms as u64 * 1000);
    81→        current_time_us < end_time
    82→    }
    83→
    84→    pub fn get_elapsed_ms(&self, current_time_us: u64) -> u32 {
    85→        if current_time_us < self.start_time_us {
    86→            return 0;
    87→        }
    88→        ((current_time_us - self.start_time_us) / 1000) as u32
    89→    }
    90→
    91→    pub fn get_remaining_ms(&self, current_time_us: u64) -> u32 {
    92→        let elapsed = self.get_elapsed_ms(current_time_us);
    93→        if elapsed >= self.duration_ms {
    94→            return 0;
    95→        }
    96→        self.duration_ms - elapsed
    97→    }
    98→}
