    48→    pub fn initialize_for_process(stack_addr: u64) -> Self {
    49→        let mut regs = GeneralPurposeRegisters::new();
    50→        regs.rsp = stack_addr;  // 스택 포인터 초기화
    51→        regs.rbp = stack_addr;  // 베이스 포인터 초기화
    52→        regs
    53→    }
    54→
    55→    pub fn get_all_registers(&self) -> [u64; 8] {
    56→        [
    57→            self.rax, self.rbx, self.rcx, self.rdx,
    58→            self.rsi, self.rdi, self.rbp, self.rsp,
    59→        ]
    60→    }
    61→
    62→    pub fn set_all_registers(&mut self, values: [u64; 8]) {
    63→        self.rax = values[0];
    64→        self.rbx = values[1];
    65→        self.rcx = values[2];
    66→        self.rdx = values[3];
