    13→
    14→# find(arr, fn) - 조건에 맞는 첫 요소
    15→fn find(arr: [any], fn: fn(any)->bool): any {
    16→  # 주석: fn이 true를 반환하는 첫 요소 반환
    17→  # 예: find([1,2,3,4], fn(x)->x>2) -> 3
    18→  let i = 0
    19→  while i < len(arr) {
    20→    if fn(arr[i]) {
    21→      return arr[i]
    22→    }
    23→    i = i + 1
    24→  }
    25→  return null
    26→}
    27→
    28→# findIndex(arr, fn) - 조건에 맞는 인덱스
    29→fn findIndex(arr: [any], fn: fn(any)->bool): i32 {
    30→  # 주석: fn이 true를 반환하는 첫 요소의 인덱스
    31→  # 예: findIndex([1,2,3,4], fn(x)->x>2) -> 2
    32→  let i = 0
    33→  while i < len(arr) {
    34→    if fn(arr[i]) {
    35→      return i
    36→    }
    37→    i = i + 1
    38→  }
    39→  return -1
    40→}
    41→
    42→# findLast(arr, fn) - 조건에 맞는 마지막 요소
    43→fn findLast(arr: [any], fn: fn(any)->bool): any {
    44→  # 주석: fn이 true를 반환하는 마지막 요소
    45→  # 예: findLast([1,2,3,2,1], fn(x)->x>1) -> 3
    46→  let result = null
    47→  let i = 0
    48→  while i < len(arr) {
    49→    if fn(arr[i]) {
    50→      result = arr[i]
    51→    }
    52→    i = i + 1
    53→  }
    54→  return result
    55→}
    56→
    57→# findLastIndex(arr, fn) - 조건에 맞는 마지막 인덱스
    58→fn findLastIndex(arr: [any], fn: fn(any)->bool): i32 {
    59→  # 주석: fn이 true를 반환하는 마지막 요소의 인덱스
    60→  let result = -1
    61→  let i = 0
    62→  while i < len(arr) {
    63→    if fn(arr[i]) {
    64→      result = i
    65→    }
    66→    i = i + 1
    67→  }
    68→  return result
    69→}
    70→
    71→# ================================================================
    72→# 섹션 2: 고급 검증
    73→# ================================================================
    74→
    75→# some(arr, fn) - 하나라도 조건을 만족하는가
    76→fn some(arr: [any], fn: fn(any)->bool): bool {
    77→  # 주석: 하나라도 fn이 true를 반환하면 true
    78→  # 예: some([1,2,3], fn(x)->x>2) -> true
    79→  let i = 0
    80→  while i < len(arr) {
    81→    if fn(arr[i]) {
    82→      return true
    83→    }
    84→    i = i + 1
    85→  }
    86→  return false
    87→}
    88→
    89→# every(arr, fn) - 모두 조건을 만족하는가
    90→fn every(arr: [any], fn: fn(any)->bool): bool {
    91→  # 주석: 모두 fn이 true를 반환해야 true
    92→  # 예: every([1,2,3], fn(x)->x>0) -> true
    93→  let i = 0
    94→  while i < len(arr) {
    95→    if not(fn(arr[i])) {
    96→      return false
    97→    }
    98→    i = i + 1
    99→  }
   100→  return true

