     9→// DegradationLevel: 5단계 성능 저하 레벨
    10→enum DegradationLevel {
    11→    Level0,  // 100% performance - 정상 (CPU/메모리 모두 충분)
    12→    Level1,  //  85% performance -   경고 (메모리 75-80%)
    13→    Level2,  //  70% performance -   주의 (메모리 80-90%)
    14→    Level3,  //  50% performance -   심각 (메모리 90-98%)
    15→    Level4,  //  30% performance - 긴급 (메모리 98%+, 시스템 생존 우선)
    16→}
    17→
    18→impl DegradationLevel {
    19→    fn performance_factor(&self) -> f64 {
    20→        match self {
    21→            DegradationLevel::Level0 => 1.00,   // 100%
    22→            DegradationLevel::Level1 => 0.85,   //  85%
    23→            DegradationLevel::Level2 => 0.70,   //  70%
    24→            DegradationLevel::Level3 => 0.50,   //  50%
    25→            DegradationLevel::Level4 => 0.30,   //  30%
    26→        }
    27→    }
    28→
    29→    fn target_saturation(&self) -> f64 {
    30→        match self {
    31→            DegradationLevel::Level0 => 0.75,
    32→            DegradationLevel::Level1 => 0.80,
    33→            DegradationLevel::Level2 => 0.90,
    34→            DegradationLevel::Level3 => 0.98,
    35→            DegradationLevel::Level4 => 1.00,
    36→        }
    37→    }
    38→
    39→    fn description(&self) -> String {
    40→        match self {
    41→            DegradationLevel::Level0 => "Normal operation, full performance".to_string(),
    42→            DegradationLevel::Level1 => "Caution: 85% performance, memory warning".to_string(),
    43→            DegradationLevel::Level2 => "Warning: 70% performance, memory pressure".to_string(),
    44→            DegradationLevel::Level3 => "Critical: 50% performance, emergency measures active".to_string(),
    45→            DegradationLevel::Level4 => "Emergency: 30% performance, survival mode, system stability prioritized".to_string(),
    46→        }
    47→    }
    48→}
